    for (int i = 0; i < FIELD_COUNT; ++i) api.name(&field_names[i], fields[i], false);
    const char *labels[] = {"id", "point", "goal_or_reach", "speed", "stop_range", "tick_hz", "passing"};
    for (int i = 0; i < 7; ++i) api.name(&argument_names[i], labels[i], false);
